/* Exact combinational contracts; routes show dependencies, not electrical delay. */
"use strict";
(()=>{
const esc=s=>String(s).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const copy=x=>JSON.parse(JSON.stringify(x));
const bit=(x,i)=>(x>>i)&1,bin=(x,n)=>x.toString(2).padStart(n,'0');
const text=(x,y,s,cls='mx-label')=>s===''?'':`<text x="${x}" y="${y}" class="${cls}">${esc(s).replace(/([a-zA-Z])([0-9])/g,'$1<tspan class="mx-index" baseline-shift="sub">$2</tspan>')}</text>`;
const wire=(p,on=false)=>`<polyline points="${p.map(v=>v.join(',')).join(' ')}" fill="none" stroke="${on?'#187e79':'#8fa2af'}" stroke-width="${on?3.5:2}"/>`;
const rect=(x,y,w,h,on=false)=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="7" fill="${on?'#d8eee9':'#f5f8fa'}" stroke="#698695" stroke-width="1.7"/>`;
const mux=(x,y,w,h,label)=>`<path d="M${x},${y} L${x+w},${y+18} L${x+w},${y+h-18} L${x},${y+h} Z" fill="#edf4f7" stroke="#426f82" stroke-width="2"/>`+text(x+20,y+h/2+7,label,'mx-gate');
const svg=(body,h=420)=>`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1000 ${h}" role="img" aria-label="Exact labeled selection circuit">${body}</svg>`;
const segments=['1111110','0110000','1101101','1111001','0110011','1011011','1011111','1110000','1111111','1111011'];
function evaluate(s){
 const N=2**s.n,A=s.address,D=s.data,R=s.requests;
 switch(s.operation){
 case'mux':return {address:A,output:D[A],data:copy(D)};
 case'tree':{let level=copy(D),levels=[copy(level)];for(let k=0;k<s.n;k++){const v=bit(A,k);level=Array.from({length:level.length/2},(_,j)=>level[2*j+v]);levels.push(copy(level));}return{address:A,levels,output:level[0]};}
 case'shannon':{const co=[1-s.residual,1-s.residual,0,1];return{address:A,residual:s.residual,data:co,output:co[A]};}
 case'decoder':case'banks':case'demux':{const active=s.operation==='demux'?s.residual:s.enable;const v=Array.from({length:N},(_,i)=>active&&i===A?1:0);return{address:A,logical:v,pins:s.polarity==='low'?v.map(x=>1-x):v,enabled:active,bank:Math.floor(A/4),local:A%4};}
 case'priority':{const indices=Array.from({length:N},(_,i)=>i).filter(i=>bit(R,i));const winner=indices.length?(s.order==='low'?indices[0]:indices.at(-1)):null;const grants=Array.from({length:N},(_,i)=>i===winner?1:0);return{requests:R,winner,code:winner??0,valid:Number(winner!==null),grants};}
 case'rotate':{const order=Array.from({length:N},(_,j)=>(s.pointer+j)%N),winner=order.find(i=>bit(R,i))??null;return{requests:R,order,winner,code:winner??0,valid:Number(winner!==null),grants:Array.from({length:N},(_,i)=>i===winner?1:0)};}
 case'rom':return{address:A,row:Math.floor(A/4),column:A%4,output:D[A],data:copy(D)};
 case'display':{const pattern=segments[A]??'0000000';return{address:A,pattern:s.polarity==='low'?[...pattern].map(c=>1-Number(c)).join(''):pattern,lit:pattern,valid:Number(A<10)};}
 case'bus':{const owners=s.enables.map((e,i)=>e?i:null).filter(i=>i!==null),values=owners.map(i=>D[i]),conflict=new Set(values).size>1;return{owners,values,value:owners.length?(conflict?'CONFLICT':values[0]):'Z',singleOwner:owners.length===1,contractViolation:owners.length>1};}
 case'integrated':{const carry=Number(s.a+s.b+1>=2),sum=(s.a+s.b+1)%2,t=sum^carry,co=[1-carry,carry,t,1-t];return{a:s.a,b:s.b,address:A,carry,sum,t,data:co,output:co[A]};}
 case'cascade':{const t=1-s.b,output=s.a?0:t;return{a:s.a,b:s.b,t,output};}
 default:throw Error('Unknown operation.');
 }
}
function validate(raw){const s={operation:'mux',n:2,address:0,data:[0,1,1,0],requests:0,enable:1,polarity:'high',residual:0,pointer:0,a:0,b:0,enables:[0,0],...copy(raw)};if(!Number.isInteger(s.n)||s.n<1||s.n>4)throw Error('Address width must be an integer from one through four.');const N=2**s.n;if(!Number.isInteger(s.address)||s.address<0||s.address>=N)throw Error('Address must fit its width.');for(const k of['enable','residual','a','b'])if(![0,1].includes(s[k]))throw Error(k+' must be zero or one.');if(!['high','low'].includes(s.polarity))throw Error('Polarity must be high or low.');if(!Number.isInteger(s.requests)||s.requests<0||s.requests>=2**N)throw Error('Request word must fit the decoded request count.');if(!Number.isInteger(s.pointer)||s.pointer<0||s.pointer>=N)throw Error('Starting pointer must fit the request count.');if(['mux','tree','rom'].includes(s.operation)&&(!Array.isArray(s.data)||s.data.length!==N||s.data.some(x=>!Number.isInteger(x)||x<0||x>255)))throw Error('Supply exactly '+N+' integer data words from zero through 255.');if(['shannon','integrated'].includes(s.operation)&&s.n!==2)throw Error('This cofactor example uses two selectors.');if(s.operation==='cascade'&&s.n!==1)throw Error('The cascade example uses one-bit selectors.');if(s.operation==='tree'&&s.n>3)throw Error('The diagram supports at most eight tree leaves.');if(s.operation==='banks'&&s.n!==3)throw Error('The bank expansion example uses a three-bit address.');if(s.operation==='display'&&s.n!==4)throw Error('The display example uses a four-bit BCD address.');if(s.operation==='rom'&&s.n!==4)throw Error('The ROM organization example uses sixteen rows and a two-bit column split.');if(s.operation==='bus'&&(!Array.isArray(s.data)||s.data.length!==2||s.data.some(x=>![0,1].includes(x))||!Array.isArray(s.enables)||s.enables.length!==2||s.enables.some(x=>![0,1].includes(x))))throw Error('Two bus data and enable bits are required.');if(!['high','low'].includes(s.order??'high'))throw Error('Priority must be high or low.');s.order??='high';return s;}
function selectorDiagram(s,r,p){const d=r.data,step=p.phase;let b=text(30,34,'Addressed data: MSB-first select order')+text(30,72,'A highlighted route is selected even when its value is zero.');const N=d.length,dy=42,h=N*dy+28,y=108,x=390,w=155; b+=mux(x,y,w,h,N+':1');for(let i=0;i<N;i++){const yy=y+24+i*dy;b+=text(110,yy+6,'I'+i+' = '+d[i],'mx-math')+wire([[235,yy],[x,yy]],step>0&&i===r.address);b+=text(555,yy+6,step>0&&i===r.address?'selected':'');}const oy=y+h/2;b+=wire([[x+w,oy],[840,oy]],step>1)+text(855,oy+6,step>1?'y = '+r.output:'y = ?','mx-math');b+=wire([[470,y+h+35],[470,y+h-9]],step>0)+text(290,y+h+61,'select = '+bin(r.address,s.n),'mx-math');return svg(b,Math.max(420,y+h+85));}
function treeDiagram(s,r,p){const N=s.data.length,cols=s.n,dy=75;let b=text(30,34,'Binary selector tree: lower select bits act first')+text(30,72,'Each stage chooses adjacent values; wires connect named cell ports.');let ports=s.data.map((v,i)=>({x:150,y:120+i*dy,value:v}));for(let i=0;i<N;i++)b+=text(32,ports[i].y+6,'I'+i+' = '+s.data[i],'mx-math');for(let k=0;k<cols;k++){const x=235+k*235,next=[];for(let j=0;j<ports.length/2;j++){const u=ports[2*j],v=ports[2*j+1],cy=(u.y+v.y)/2,yy=cy-43;b+=mux(x,yy,85,86,'2:1')+wire([[u.x,u.y],[x-32,u.y],[x-32,cy-20],[x,cy-20]],p.phase>k&&bit(r.address,k)===0)+wire([[v.x,v.y],[x-15,v.y],[x-15,cy+20],[x,cy+20]],p.phase>k&&bit(r.address,k)===1);b+=wire([[x+44,yy+116],[x+44,yy+81]],p.phase>k)+text(x+7,yy+140,'s'+k+' = '+bit(r.address,k),'mx-math');next.push({x:x+85,y:cy,value:r.levels[k+1][j]});b+=text(x+95,cy-9,p.phase>k?String(next.at(-1).value):'?','mx-math');}ports=next;}b+=wire([[ports[0].x,ports[0].y],[950,ports[0].y]],p.phase>=cols);return svg(b,Math.max(420,120+(N-1)*dy+160));}
function gateDecoderDiagram(s,r,p){let b=text(30,34,'Enabled 2:4 decoder: shared inversions and four AND minterms')+text(30,72,'Junction dots mark connected buses; unmarked wire crossings are not connections.');const bus=[160,260,360,460,560],values=[bit(s.address,1),1-bit(s.address,1),bit(s.address,0),1-bit(s.address,0),s.enable],names=['a1','¬a1','a0','¬a0','e'];for(let i=0;i<5;i++)b+=text(bus[i]-28,117,names[i]+' = '+values[i],'mx-math')+wire([[bus[i],145],[bus[i],580]],p.phase>0);for(const x of[160,360])b+=wire([[x,145],[x+32,145]])+`<path d="M${x+32},127 L${x+65},145 L${x+32},163 Z" fill="#edf4f7" stroke="#426f82" stroke-width="2"/><circle cx="${x+71}" cy="145" r="6" fill="white" stroke="#426f82" stroke-width="2"/>`+wire([[x+77,145],[x+100,145]]);for(let i=0;i<4;i++){const y=190+i*100,x1=bit(i,1)?160:260,x0=bit(i,0)?360:460;for(const[x,dy]of[[560,13],[x1,36],[x0,59]])b+=wire([[x,y+dy],[650,y+dy]],p.phase>0)+`<circle cx="${x}" cy="${y+dy}" r="3.5" fill="#426f82"/>`;b+=`<path d="M650,${y} L686,${y} A36,36 0 0 1 686,${y+72} L650,${y+72} Z" fill="${p.phase>1&&r.logical[i]?'#d8eee9':'#f5f8fa'}" stroke="#426f82" stroke-width="2"/>`+wire([[722,y+36],[840,y+36]],p.phase>1&&r.logical[i]===1)+text(860,y+42,'D'+i+' = '+(p.phase>1?r.logical[i]:'?'),'mx-math');}b+=text(30,625,'Every gate combines enable with the two literals of one complete address minterm.');return svg(b,660);}
function decoderDiagram(s,r,p){const N=r.pins.length;let b=text(30,34,s.operation==='demux'?'Data-gated routing to one destination':'Address predicates and output polarity')+text(30,72,'Output index equals the binary address; enable determines assertion.');const y=110,h=N*38+30; b+=rect(390,y,180,h)+text(415,y+h/2,'DECODER');b+=wire([[165,y+45],[390,y+45]],p.phase>0)+text(30,y+51,'address = '+bin(s.address,s.n),'mx-math')+wire([[165,y+h-25],[390,y+h-25]],p.phase>0)+text(30,y+h-19,(s.operation==='demux'?'data':'enable')+' = '+r.enabled,'mx-math');for(let i=0;i<N;i++){const yy=y+24+i*38;b+=wire([[570,yy],[795,yy]],p.phase>1&&r.logical[i]===1);if(s.polarity==='low')b+=`<circle cx="577" cy="${yy}" r="6" fill="white" stroke="#426f82"/>`;b+=text(815,yy+6,(s.polarity==='low'?'L':'D')+i+' = '+(p.phase>1?r.pins[i]:'?'),'mx-math');}return svg(b,Math.max(420,y+h+42));}
function banksDiagram(s,r,p){let b=text(30,34,'3:8 expansion: a high-bit bank and a local two-bit address')+text(30,72,'Each bank has its own enable; only the chosen bank may assert a pin.');const high=bit(s.address,2);for(let bank=0;bank<2;bank++){const x=250+bank*420,y=140;b+=rect(x,y,165,220,bank===r.bank&&p.phase>0)+text(x+20,y+38,'2:4 decoder')+text(x+20,y+77,'local = '+bin(r.local,2),'mx-math')+wire([[x-80,y+95],[x,y+95]],p.phase>0&&r.enabled&&bank===r.bank)+text(x-80,y+126,'EN = '+(r.enabled&&bank===r.bank?1:0),'mx-math');for(let j=0;j<4;j++){const yy=y+125+28*j;b+=wire([[x+165,yy],[x+230,yy]],p.phase>1&&r.logical[bank*4+j]===1)+text(x+242,yy+6,'D'+(bank*4+j)+' = '+(p.phase>1?r.logical[bank*4+j]:'?'),'mx-math');}}b+=text(30,410,'a2 = '+high+'; global enable = '+s.enable+'; local address a1a0 = '+bin(r.local,2),'mx-math');return svg(b,455);}
function priorityDiagram(s,r,p){const N=2**s.n;let b=text(30,34,s.operation==='rotate'?'Rotating search with a supplied starting pointer':'Priority suppression: grants precede binary encoding')+text(30,72,'Request indices increase from right to left in the written word.');const order=s.operation==='rotate'?r.order:Array.from({length:N},(_,j)=>s.order==='low'?j:N-1-j);for(let j=0;j<N;j++){const i=order[j],x=40+j*112;b+=rect(x,125,96,94,p.phase>0&&j<(p.scanned??N))+text(x+16,155,'r'+i+' = '+bit(s.requests,i),'mx-math')+text(x+16,193,p.decided?(i===r.winner?'grant':(bit(s.requests,i)?'blocked':'absent')):(j<p.scanned?'absent':'pending'));}b+=text(40,275,'Search order: '+order.join(' → '),'mx-math');b+=text(40,327,p.encoded?'valid = '+r.valid+'; code = '+bin(r.code,s.n)+'; winner = '+(r.winner??'none'):'The winner is not encoded until the priority decision is complete.','mx-math');b+=text(40,382,'Only one grant can feed the ordinary encoder.');return svg(b,420);}
function romDiagram(s,r,p){let b=text(30,34,'16-word ROM: two row bits and two column bits')+text(30,72,'The two-bit column selector picks one word from the selected row.');for(let row=0;row<4;row++){b+=text(30,144+row*62,'row '+row,'mx-math');for(let col=0;col<4;col++){const x=170+col*154,y=113+row*62,on=p.phase>0&&row===r.row; b+=rect(x,y,136,50,on)+text(x+15,y+32,String(s.data[4*row+col]),'mx-math');if(p.phase>1&&row===r.row&&col===r.column)b+=`<rect x="${x+4}" y="${y+4}" width="128" height="42" rx="5" fill="none" stroke="#187e79" stroke-width="3"/>`;}}b+=text(825,165,'row = '+r.row,'mx-math')+text(825,209,'col = '+r.column,'mx-math')+text(825,265,p.phase>1?'y = '+r.output:'y = ?','mx-math');b+=text(30,395,'Address '+s.address+' = 4 × '+r.row+' + '+r.column+'; total capacity is unchanged.','mx-math');return svg(b);}
function displayDiagram(s,r,p){let b=text(30,34,'Seven-segment output: conventional a through g geometry')+text(30,72,'Lit geometry is independent of the numerical polarity of the external pins.');const lines=[[430,120,565,120],[583,138,583,228],[583,266,583,356],[430,374,565,374],[412,266,412,356],[412,138,412,228],[430,247,565,247]];lines.forEach((v,i)=>{const on=p.phase>1&&r.lit[i]==='1';b+=`<line x1="${v[0]}" y1="${v[1]}" x2="${v[2]}" y2="${v[3]}" stroke="${on?'#187e79':'#dce4ea'}" stroke-width="17" stroke-linecap="round"/>`;b+=text([492,619,619,492,360,360,492][i],[101,188,319,407,319,188,276][i],'abcdefg'[i],'mx-math');});b+=text(30,150,'BCD = '+s.address,'mx-math')+text(30,202,'legal digit = '+r.valid,'mx-math')+text(30,255,'polarity = '+s.polarity)+text(675,200,'pins abcdefg','mx-math')+text(675,244,p.phase>1?r.pattern:'???????','mx-math');return svg(b,440);}
function busDiagram(s,r,p){let b=text(30,34,'Tri-state bus: Z, driven value, or incompatible drive')+text(30,72,'The figure classifies a contract; it does not calculate voltage or current.');for(let i=0;i<2;i++){const y=155+i*150,x=380;b+=`<path d="M${x},${y-35} L${x+90},${y} L${x},${y+35} Z" fill="${s.enables[i]?'#d8eee9':'#f5f8fa'}" stroke="#426f82" stroke-width="2"/>`+wire([[210,y],[x,y]],p.phase>0&&s.enables[i])+text(30,y+6,'driver '+i+': data '+s.data[i])+wire([[x+45,y+80],[x+45,y+17]],p.phase>0)+text(x-15,y+105,'EN = '+s.enables[i],'mx-math')+wire([[x+90,y],[700,y]],p.phase>1&&s.enables[i]);}b+=wire([[700,155],[700,305]])+text(745,235,p.phase>1?'bus: '+r.value:'bus: pending')+text(745,280,'owners = '+r.owners.length,'mx-math');return svg(b,445);}
function integratedDiagram(s,r,p){let b=text(30,34,'Full-adder, XOR, two inversions, and an addressed output')+text(30,72,'Ports are shown in descending index order, as in the original examination circuit.');
b+=rect(150,220,135,150)+text(166,251,'Full adder')+text(166,290,p.phase>0?'S = '+r.sum:'S = ?','mx-math')+text(166,341,p.phase>0?'C = '+r.carry:'C = ?','mx-math');
for(const[y,label,v]of[[245,'a',s.a],[285,'b',s.b],[350,'Cin',1]])b+=text(30,y+6,label+' = '+v,'mx-math')+wire([[100,y],[150,y]]);
b+=rect(370,122,105,75)+text(393,153,'XOR')+text(393,184,p.phase>1?'t = '+r.t:'t = ?','mx-math');
b+=wire([[285,280],[310,280],[310,142],[370,142]],p.phase>0)+wire([[285,330],[330,330],[330,178],[370,178]],p.phase>0)+`<circle cx="330" cy="330" r="3.5" fill="#426f82"/>`;
b+=wire([[330,330],[510,330],[510,304],[720,304]],p.phase>1)+wire([[330,330],[330,400],[585,400]],p.phase>1);
b+=wire([[475,158],[530,158],[530,228],[720,228]],p.phase>1)+wire([[530,158],[585,158]],p.phase>1)+`<circle cx="530" cy="158" r="3.5" fill="#426f82"/>`;
for(const[y,port]of[[158,152],[400,380]]){b+=`<path d="M585,${y-24} L625,${y} L585,${y+24} Z" fill="#edf4f7" stroke="#426f82" stroke-width="2"/><circle cx="631" cy="${y}" r="6" fill="white" stroke="#426f82" stroke-width="2"/>`+wire([[637,y],[678,y],[678,port],[720,port]],p.phase>1);}
b+=mux(720,120,110,300,'4:1');for(const[i,y]of[[3,152],[2,228],[1,304],[0,380]])b+=text(650,y-12,'I'+i+' = '+(p.phase>1?r.data[i]:'?'),'mx-math');
b+=wire([[830,270],[915,270]],p.phase>2)+text(930,276,p.phase>2?String(r.output):'?','mx-math')+wire([[772,476],[772,410]],p.phase>2)+text(670,510,'select = '+bin(s.address,2),'mx-math');return svg(b,540);}
function cascadeDiagram(s,r,p){let b=text(30,34,'Authentic two-selector NOR circuit')+text(30,72,'Select zero chooses the upper data port in both blocks.');b+=mux(240,140,120,145,'2:1')+mux(660,140,120,145,'2:1');for(const[x,v,yy]of[[240,1,176],[240,0,247],[660,p.phase>0?r.t:'?',176],[660,0,247]]){b+=text(x-105,yy-9,'I'+(yy===176?0:1)+' = '+v,'mx-math')+wire([[x-35,yy],[x,yy]],p.phase>0&&(x===240?s.b===Number(yy!==176):s.a===Number(yy!==176)));}b+=wire([[360,212],[465,212],[465,176],[660,176]],p.phase>0)+wire([[780,212],[890,212]],p.phase>1)+text(900,218,p.phase>1?String(r.output):'?','mx-math');for(const[x,label,v]of[[300,'b',s.b],[720,'a',s.a]])b+=wire([[x,358],[x,273]])+text(x-50,393,label+' = '+v,'mx-math');return svg(b,425);}
function draw(s,r,p){if(['mux','shannon'].includes(s.operation))return selectorDiagram(s,r,p);if(s.operation==='tree')return treeDiagram(s,r,p);if(s.operation==='decoder'&&s.diagram==='gates')return gateDecoderDiagram(s,r,p);if(['decoder','demux'].includes(s.operation))return decoderDiagram(s,r,p);if(s.operation==='banks')return banksDiagram(s,r,p);if(['priority','rotate'].includes(s.operation))return priorityDiagram(s,r,p);if(s.operation==='rom')return romDiagram(s,r,p);if(s.operation==='display')return displayDiagram(s,r,p);if(s.operation==='bus')return busDiagram(s,r,p);if(s.operation==='integrated')return integratedDiagram(s,r,p);return cascadeDiagram(s,r,p);}
function makeModel(id,title,raw){const s=validate(raw);if(['priority','rotate'].includes(s.operation)&&s.n>3)throw Error('Priority diagrams support at most eight requests.');const r=evaluate(s),frames=[];let labels=['Read the declared input contract','Compute the selected address or predicate','Propagate the selected result'];if(s.operation==='tree')labels=['Read source words',...Array.from({length:s.n},(_,i)=>'Evaluate selector level '+(i+1))];if(s.operation==='integrated')labels=['Read a, b, and fixed carry-in','Compute full-adder sum and carry','Compute XOR and the four data cofactors','Select the labeled data port'];if(s.operation==='rom')labels=['Read the address and stored words','Select the row by integer quotient','Select the column by remainder'];if(['priority','rotate'].includes(s.operation))labels=['Read requests and explicit priority order','Suppress outranked requests','Encode only the winning grant'];if(['priority','rotate'].includes(s.operation)){const order=s.operation==='rotate'?r.order:Array.from({length:2**s.n},(_,j)=>s.order==='low'?j:2**s.n-1-j);const k=r.winner===null?order.length:order.indexOf(r.winner)+1;labels=['Read requests and the declared search order',...order.slice(0,k).map(i=>'Inspect request index '+i+' = '+bit(s.requests,i)),r.winner===null?'Confirm that no request exists':'Encode the resolved winning index'];}const reasons={mux:'Only the addressed data port contributes; selection remains meaningful when its data value is zero.',shannon:'The residual-variable pair determines each data cofactor; do not replace a complement by the variable.',tree:'The low address bit selects adjacent leaves first; subsequent bits choose increasingly large groups.',decoder:'Equality creates one address predicate, then enable and output polarity determine the pins.',banks:'The high address bit activates one bank; the low two bits retain their local output index.',demux:'Data gates the selected predicate, so zero data produces no asserted output even though a route is selected.',priority:'A higher-priority request suppresses every lower grant; validity is independent of the inactive code.',rotate:'The supplied pointer determines a circular search order; no sequential fairness is implied.',rom:'Quotient selects a row and remainder selects a column while preserving stored capacity.',display:'Geometric illumination is derived from the digit contract; active-low pins complement the pattern.',bus:'Disabled drivers disconnect; incompatible enabled values create contention rather than Boolean OR.',integrated:'The arithmetic stage and XOR establish the data vector before the independent selectors choose a port.',cascade:'Derive the first cofactor before substituting it into the second selector.'};for(let phase=0;phase<labels.length;phase++){const p={phase};if(['priority','rotate'].includes(s.operation)){const order=s.operation==='rotate'?r.order:Array.from({length:2**s.n},(_,j)=>s.order==='low'?j:2**s.n-1-j);const count=r.winner===null?order.length:order.indexOf(r.winner)+1;p.scanned=Math.min(phase,count);p.decided=phase>=count;p.encoded=phase===labels.length-1;}const visible=phase===labels.length-1;const caption=labels[phase];frames.push({svg:draw(s,r,p),caption,formula:'',snapshot:{step:phase+1,inputAddress:!['priority','rotate','bus','cascade'].includes(s.operation)?s.address:'not used',requestWord:['priority','rotate'].includes(s.operation)?bin(s.requests,2**s.n):'not used',selectedIndex:visible?(r.winner??r.address??'none'):'not resolved',output:visible?(r.output??r.code??r.value??r.pattern??'see output vector'):'not evaluated',inputs:copy(s),result:visible?copy(r):null},teaching:{currentState:caption,operation:caption,why:reasons[s.operation],reading:visible?'Compare the exact result with the declared input contract.':'Read the named ports and highlighted dependency before advancing.',checks:[{mathHtml:'Input domain',result:'validated'},{mathHtml:'Electrical scope',result:'logical model only'}]}});}return{id,title,kind:'exact-routing',invariant:reasons[s.operation],spec:s,frames,result:r};}
if(typeof module!=='undefined')module.exports={makeModel,evaluate,validate};
if(typeof document==='undefined')return;
function mount(host,m){if(!host.querySelector('.mx-controls')){const c=document.createElement('div');c.className='mx-controls';c.innerHTML='<button type="button" data-reset>Restart</button><button type="button" data-prev>Previous</button><button type="button" data-play>Play</button><button type="button" data-next>Next</button><label>Speed<select data-speed></select></label><label>Step<input type="range" data-seek min="0" value="0"></label>';host.querySelector('.mx-stage').before(c);}for(const cls of['mx-caption','mx-formula','mx-print'])if(!host.querySelector('.'+cls)){const e=document.createElement('div');e.className=cls;host.append(e);}return AdvancedSimulations.mount(host,m,{topic:'g_mux',prefix:'mx',retainDrawing:true});}
async function boot(){const data=await(await fetch('g_mux-models.json')).json();globalThis.MuxPlayers=[];for(const host of document.querySelectorAll('[data-mx-model]')){const m=data.models.find(m=>m.id===host.dataset.mxModel);if(!m)throw Error('Missing model '+host.dataset.mxModel);MuxPlayers.push(mount(host,m));}const form=document.querySelector('#mx-form'),out=document.querySelector('#mx-output'),error=document.querySelector('#mx-error');let active=null;form.addEventListener('submit',ev=>{ev.preventDefault();try{const f=form.elements,operation=f.operation.value,n=Number(f.n.value),spec={operation,n,address:Number(f.address.value),data:f.data.value.split(',').map(x=>Number(x.trim())),requests:Number(f.requests.value),residual:Number(f.residual.value),enable:Number(f.enable.value),polarity:f.polarity.value,order:f.order.value,pointer:Number(f.pointer.value),a:Number(f.a.value),b:Number(f.b.value),enables:f.enables.value.split(',').map(x=>Number(x.trim()))};if(!f.data.value.trim()||f.data.value.split(',').some(x=>!x.trim()))throw Error('Data values cannot be empty.');const m=makeModel('editable-mux','Your '+operation+' contract',spec);active?.dispose();out.innerHTML='<section class="mx-model"><h3>'+esc(m.title)+'</h3><div class="mx-stage"></div></section><h3>Checked result</h3><pre>'+esc(JSON.stringify(m.result,null,2))+'</pre>';active=mount(out.firstChild,m);globalThis.MuxLab=active;error.textContent='';}catch(e){error.textContent=e.message;}});form.dispatchEvent(new Event('submit',{cancelable:true}));}
boot().catch(e=>{document.querySelector('#mx-error').textContent=e.message;throw e;});
})();
